package com.nextrade.common.util; import java.nio.charset.StandardCharsets; import java.security.*; public final class Hashing {private Hashing(){} public static String sha256(String input){try{byte[] d=MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8)); StringBuilder b=new StringBuilder(d.length*2);for(byte x:d)b.append(String.format("%02x",x));return b.toString();}catch(GeneralSecurityException e){throw new IllegalStateException(e);}} public static boolean constantTimeEquals(String a,String b){if(a==null||b==null)return false;return MessageDigest.isEqual(a.getBytes(StandardCharsets.UTF_8),b.getBytes(StandardCharsets.UTF_8));}}